<div id="__nuxt"><div><main id="main-content" class="default-layout__main"><!--[--><div data-page="[uid].vue"><div class="outer-container"><div><!--[--><section id="cookie-policy-for-evri" class="section-wrapper rich-text" index="0" data-v-92714c58 data-v-ebc71926><div class="section-wrapper__container" data-v-ebc71926><!--[--><!--[--><h1><!--[--><!--[--><strong><!--[--><!--[--><!--[--><!--[--><!--v-if-->Cookie policy for Evri<!--]--><!--]--><!--]--><!--]--></strong><!--]--><!--]--></h1><h2><!--[--><!--[--><strong><!--[--><!--[--><!--[--><!--[--><!--v-if-->Topics:<!--]--><!--]--><!--]--><!--]--></strong><!--]--><!--]--></h2><ul><!--[--><!--[--><li><!--[--><!--[--><!--[--><!--[--><!--v-if-->How to control and delete cookies<!--]--><!--]--><!--]--><!--]--></li><li><!--[--><!--[--><!--[--><!--[--><!--v-if-->List of the main Evri Cookies<!--]--><!--]--><!--]--><!--]--></li><li><!--[--><!--[--><!--[--><!--[--><!--v-if-->Third Party Cookies<!--]--><!--]--><!--]--><!--]--></li><li><!--[--><!--[--><!--[--><!--[--><!--v-if-->Evri Sharing Tools<!--]--><!--]--><!--]--><!--]--></li><!--]--><!--]--></ul><h2><!--[--><!--[--><strong><!--[--><!--[--><!--[--><!--[--><!--v-if-->1. How to control and delete cookies<!--]--><!--]--><!--]--><!--]--></strong><!--]--><!--]--></h2><p><!--[--><!--[--><!--[--><!--[--><!--v-if-->Evri will not use cookies to collect personally identifiable information about you. However, if you wish to restrict or block the cookies which are set by Evri websites, you can do so through the &quot;No, take me to settings&quot; button on our cookie banner. If you have already set your preferences and wish to change them, clear your cookies for evri.com within your browser and then you can reload the page and set your preferences once more.<!--]--><!--]--><!--]--><!--]--></p><p><!--[--><!--[--><!--[--><!--[--><!--v-if-->Alternatively, you may wish to visit <!--]--><!--]--><strong><!--[--><!--[--><a href="http://www.aboutcookies.org/" rel="noreferrer" target="_blank"><!--[--><!--[--><!--[--><!--[--><!--[--><!--v-if-->www.aboutcookies.org<!--]--><!--]--><!--]--><!--]--><!--]--></a><!--]--><!--]--></strong><!--[--><!--[--><!--v-if--> which contains comprehensive information on how to do this on a wide variety of browsers. You will also find details on how to delete cookies from your computer as well as more general information about cookies. For information on how to do this on the browser of your mobile phone you will need to refer to your handset manual.<!--]--><!--]--><!--]--><!--]--></p><p><!--[--><!--[--><!--[--><!--[--><!--v-if-->Please be aware that restricting cookies may impact on the functionality of the Evri website. Evri may use a number of suppliers who also set cookies on the Evri websites on our behalf in order to deliver the services that they are providing. If you would like more information about the cookies used by these suppliers, as well as information on how to opt-out, please see section 3 below.<!--]--><!--]--><!--]--><!--]--></p><h2><!--[--><!--[--><strong><!--[--><!--[--><!--[--><!--[--><!--v-if-->2. List of cookies used on evri.com<!--]--><!--]--><!--]--><!--]--></strong><!--]--><!--]--></h2><p><!--[--><!--[--><!--[--><!--[--><!--v-if-->Below is a link to the list of Evri cookies used on Evri websites, including evri.com. This list includes cookie names and what they are used for.<!--]--><!--]--><!--]--><!--]--></p><p><!--[--><!--[--><!--[--><!--[--><!--v-if-->This list also includes a number of suppliers who set cookies on the Evri website on its behalf in order to deliver the services that they are providing. If you would like more information about the cookies used by these suppliers, as well as information on how to opt-out, please see their individual privacy policies.<!--]--><!--]--><!--]--><!--]--></p><p><!--[--><!--[--><!--[--><!--[--><!--v-if-->Link to cookie list: <!--]--><!--]--><strong><!--[--><!--[--><a href="/cookie-policy/cookie-list" rel="noreferrer"><!--[--><!--[--><!--[--><!--[--><!--[--><!--v-if-->www.evri.com/cookie-policy/cookie-list<!--]--><!--]--><!--]--><!--]--><!--]--></a><!--]--><!--]--></strong><!--]--><!--]--></p><h2><!--[--><!--[--><strong><!--[--><!--[--><!--[--><!--[--><!--v-if-->3. Evri Sharing Tools<!--]--><!--]--><!--]--><!--]--></strong><!--]--><!--]--></h2><p><!--[--><!--[--><!--[--><!--[--><!--v-if-->We would like to draw your attention to the fact that the Evri website carries embedded ‘share’ buttons to enable users of the site to easily share articles with their friends through a number of popular social networks. These sites may set a cookie when you are also logged in to their service. Evri does not control the dissemination of these cookies and you should check the relevant third party website for more information about these.<!--]--><!--]--><!--]--><!--]--></p><p><!--[--><!--[--><!--[--><!--[--><!--v-if--> <!--]--><!--]--><!--]--><!--]--></p><!--]--><!--]--></div></section><!--]--></div></div></div><!--]--></main></div></div><div id="teleports"></div><script>window.__NUXT__={};window.__NUXT__.config={public:{ENV_NAME:"prod",PUBLIC_PATH:"https://www.evri.com",WEB_BASE:"https://www.evri.com/",PRISMIC_REPO:"ev-mercury",DEVTOOLS:false,API_BASE:"https://api.hermesworld.co.uk/",AUTH0_USERS_ENDPOINT:"https://hermes-df-prod.eu.auth0.com/userinfo",AUTH0_CLIENT_ID:"dC8K22keYtRszHe7dnmlWSve2kP7mUBF",AUTH0_DOMAIN:"hermes-df-prod.eu.auth0.com",AUTH0_LOGIN_REDIRECT:"https://www.evri.com/",AUTH0_LOGOUT_REDIRECT:"https://www.evri.com/",ASSETLINKS_PATH:"assetlinks-prod.json",APPLE_MERCHANT_DOMAIN_PATH:"apple-developer-merchantid-domain-association-PROD.txt",APPLE_APP_SITE_ASSOCIATION_PATH:"apple-app-site-association-PROD",CHATBOT_URL:"https://chat-loader.smartagent.app/loader/main.js",FEATURE_SWITCH_URL:"https://www.evri.com/feature-switches/feature-switches.json",FINDER_URL:"https://location-finder.evri.com",BASKET_API_KEY:"4GuiGkQaE92687ICJtKNRd01hc4JBKUG",BULK_API_KEY:"WtuYb1yZMIGwLJzEm0yUzhLzPGuKS632",EVRI_API_KEY:"0DExZiK9in2ihGce7c